import{_ as o,o as a,c as i,a2 as t}from"./chunks/framework.Buc7gXeZ.js";const g=JSON.parse('{"title":"محرك نطاق البيانات","description":"","frontmatter":{},"headers":[],"relativePath":"ar/permissions/data-scope.md","filePath":"ar/permissions/data-scope.md"}'),s={name:"ar/permissions/data-scope.md"};function d(n,e,c,r,p,l){return a(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="محرك-نطاق-البيانات" tabindex="-1">محرك نطاق البيانات <a class="header-anchor" href="#محرك-نطاق-البيانات" aria-label="Permalink to &quot;محرك نطاق البيانات&quot;">​</a></h1><p>بيجاوب على سؤال &quot;أنهي صفوف يقدر المستخدم ده يشوفها&quot;، بغض النظر عن كونه مسموحله يفتح الشاشة أصلاً (ده موضوع <a href="./functional-permissions">functional-permissions.md</a>).</p><h2 id="الهيكل-التنظيمي" tabindex="-1">الهيكل التنظيمي <a class="header-anchor" href="#الهيكل-التنظيمي" aria-label="Permalink to &quot;الهيكل التنظيمي&quot;">​</a></h2><p><code>Modules/HR/Models/OrganizationStructure/</code>:</p><ul><li><strong><code>Entity</code></strong> — شركة بتديرها فعليًا (مش كل صف في <code>companies</code> — الجدول ده فيه موردين/عملاء كمان). <code>parent_entity_id</code> + عمود <code>path</code> (materialized path، زي <code>&quot;/1/4/9/&quot;</code>) بيخلوا <code>-&gt;descendantsAndSelf()</code> يلاقي كل الكيانات التابعة باستعلام <code>LIKE</code> واحد مفهرس — مفيش أبدًا recursive CTE ولا لفّة N+1 على الآباء.</li><li><strong><code>Branch</code></strong> — تابع لـ <code>Entity</code> واحدة؛ فرع رئيسي واحد بس (<code>is_main = true</code>) لكل كيان (متفروض في <code>Branch::booted()</code>، مش في قاعدة البيانات — MySQL معندهاش partial unique index).</li><li><strong><code>Department</code></strong> — <strong>صف كتالوج عام على مستوى المجموعة</strong> (شوف تحت)، مش صف لكل شركة. نفس نمط الشجرة بـ materialized path زي <code>Entity</code>.</li><li><strong><code>JobTitle</code></strong> / <strong><code>JobGrade</code></strong> — عامين على مستوى المجموعة، مش لكل كيان. <code>JobGrade.level</code> سلّم رقمي واحد مشترك (عن طريق <code>job_title_grade</code>)، فمقارنة &quot;الدرجة دي فما فوق&quot; دايمًا بتتم جوه سلّم اللقب نفسه — senior في لقب معيّن مايتقارنش أبدًا بـ senior في لقب تاني.</li></ul><h3 id="الإدارات-كتالوج-مشترك" tabindex="-1">الإدارات كتالوج مشترك <a class="header-anchor" href="#الإدارات-كتالوج-مشترك" aria-label="Permalink to &quot;الإدارات كتالوج مشترك&quot;">​</a></h3><p>جدول <code>departments</code> <strong>معندوش عمود <code>entity_id</code></strong>. &quot;المالية&quot; صف واحد بس، مشترك بين أي شركة بتستخدمه. أنهي شركات/فروع فعّلت الإدارة دي فعليًا بيتحدد في pivot <code>department_entity</code> (<code>department_id</code>, <code>entity_id</code>, <code>branch_id</code> اختياري — فاضي معناها الشركة كلها). ده مقصود: ربط إدارة بشركة وعزل نطاق البيانات جايين من مكانين مختلفين، ودمجهم هو الغلطة اللي الشكل ده بيتفاداها — شوف اختبار <a href="./testing">&quot;مدير مالي في شركة وليدة مش بياخد نطاق على شركة الأم، حتى لو بيستخدم نفس صف الإدارة&quot;</a> اللي بيثبت الكلام ده.</p><h2 id="السجل-المحوري-employee" tabindex="-1">السجل المحوري: <code>Employee</code> <a class="header-anchor" href="#السجل-المحوري-employee" aria-label="Permalink to &quot;السجل المحوري: `Employee`&quot;">​</a></h2><p><code>Modules\\HR\\Models\\EmployeeManagement\\Employee</code> هو <strong>الجسر الوحيد</strong> بين <code>User</code> مسجّل دخول والهيكل التنظيمي:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>employees: person_id, user_id (اختياري), entity_id, branch_id, department_id,</span></span>\n<span class="line"><span>           job_title_id, job_grade_id, entity_scope, department_scope, status, ...</span></span></code></pre></div><p><code>user_id</code> اختياري — مش كل موظف بيدخل النظام (عامل مصنع مثلاً). <code>User</code> بلا سطر <code>Employee</code> نشط (<code>status = &#39;active&#39;</code>) بيتحسب رفض كامل، في كل مكان — ده مقصود من التصميم، مش باج نصلّحه بـ fallback.</p><h2 id="بُعدين-نطاق-مستقلين" tabindex="-1">بُعدين نطاق مستقلين <a class="header-anchor" href="#بُعدين-نطاق-مستقلين" aria-label="Permalink to &quot;بُعدين نطاق مستقلين&quot;">​</a></h2><table tabindex="0"><thead><tr><th>العمود</th><th>القيم</th><th>بيجاوب على</th></tr></thead><tbody><tr><td><code>entity_scope</code></td><td><code>own</code> | <code>branch</code> | <code>entity</code> | <code>entity_tree</code></td><td>أنهي شركات/فروع (أفقي)</td></tr><tr><td><code>department_scope</code></td><td><code>own</code> | <code>department</code> | <code>department_tree</code> | <code>all</code></td><td>أنهي جزء من الهيكل الإداري (رأسي)</td></tr></tbody></table><p>الصفوف المرئية = <strong>تقاطع</strong> البُعدين، مش اتحاد. ده اللي بيخلّي آلية واحدة تعبّر عن كل الحالات اللي اتناقشت أثناء تصميم النظام:</p><ul><li>مدير مالي على مستوى المجموعة (<code>entity_tree</code> + <code>department_tree</code>) بيشوف القطاع المالي في الشركة الأم وكل الشركات التابعة.</li><li>نفس المدير، لو متمركز في شركة تابعة بس (<code>entity</code> + <code>department_tree</code>)، بيشوف القطاع المالي في الشركة دي بس — مش الأم، ومش الشقيقة.</li><li>موظف في فرع مش رئيسي (<code>branch</code>) محصور بالفرع ده، حتى لسجلات تانية في نفس الكيان بالظبط.</li><li><code>own</code> <strong>مش</strong> &quot;فرعه&quot; — هي صفر توسّع في entity/branch خالص. نطاق الخدمة الذاتية (موظف بيشوف طلبات إجازته هو) بُعد مختلف تمامًا (فلترة بـ <code>employee_id</code>)، مش هيتلخبط أبدًا مع <code>branch</code>.</li></ul><p><code>department_scope = department_tree</code> بيمشي على المسار الخاص بالإدارة نفسها — بلا علاقة بالكيان، مش متأثر بأنهي شركات بتشارك نفس صف الإدارة.</p><h2 id="organizationscoperesolver" tabindex="-1"><code>OrganizationScopeResolver</code> <a class="header-anchor" href="#organizationscoperesolver" aria-label="Permalink to &quot;`OrganizationScopeResolver`&quot;">​</a></h2><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$scope </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> app</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">OrganizationScopeResolver</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::class</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">resolve</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">($user); </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// OrganizationScope</span></span></code></pre></div><p>بيرجّع كائن <code>OrganizationScope</code>: <code>entityIds</code>, <code>branchIds</code>, <code>departmentIds</code>، كل واحدة إما <code>array&lt;int&gt;</code> (قائمة مسموحة محددة) أو <code>null</code> (<strong>بلا قيد</strong> — محجوزة لـ <code>super_admin</code>). مصفوفة فاضية (<code>[]</code>) معناها رفض كامل — الفرق بين <code>null</code> و<code>[]</code> هو حدود الصلاحية نفسها؛ متدمجهمش أبدًا.</p><p>ترتيب الحل:</p><ol><li>دور <code>super_admin</code> → <code>OrganizationScope::unrestricted()</code>، بلا أي بحث إضافي.</li><li>مفيش سطر <code>Employee</code> نشط لليوزر ده → <code>OrganizationScope::denyAll()</code>.</li><li>غير كده، <code>entity_scope</code> بيتحل لـ <code>[entityIds, branchIds]</code> و<code>department_scope</code> بيتحل لـ <code>departmentIds</code> كل واحد لوحده، حسب الجدول فوق.</li></ol><p><code>explain(User $user): array{scope, trace}</code> بيعمل نفس الحل <strong>بدون كاش</strong>، مع شرح كل خطوة — الأداة المخصصة لسؤال &quot;ليه المستخدم ده مش شايف السجل ده؟&quot;، مش لمسار الطلب الأساسي.</p><h3 id="الكاش-والإبطال" tabindex="-1">الكاش والإبطال <a class="header-anchor" href="#الكاش-والإبطال" aria-label="Permalink to &quot;الكاش والإبطال&quot;">​</a></h3><p><code>resolve()</code> بيتخزّن مؤقتًا تحت <code>org_scope:{user_id}:v{version}</code> بـ <code>rememberForever</code>. <code>OrganizationVersion</code> عدّاد عام واحد — زيادته مرة (عن طريق hooks الـ <code>saved</code>/<code>deleted</code> بتاعة <code>Entity</code>, <code>Branch</code>, <code>Department</code>, أو <code>Employee</code>) بتلغي كاش <strong>كل</strong> المستخدمين منطقيًا في نفس اللحظة، بدل ما ندوّر مين اتأثر بتعديل الشجرة. القراءات من غير كتابة بينهم مبتزودش العدّاد أبدًا (شوف اختبار منع الاهتزاز في <code>testing.md</code>) — <code>rememberForever</code> فعليًا مابيعملش استعلام تاني لحد ما حاجة تتغيّر فعلًا.</p><h2 id="scopedtoorganization-—-نقطة-التكامل" tabindex="-1"><code>ScopedToOrganization</code> — نقطة التكامل <a class="header-anchor" href="#scopedtoorganization-—-نقطة-التكامل" aria-label="Permalink to &quot;`ScopedToOrganization` — نقطة التكامل&quot;">​</a></h2><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">use</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> App\\Models\\Concerns\\ScopedToOrganization</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">class</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Invoice</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> extends</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Model</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    use</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> ScopedToOrganization</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>ده كل التكامل المطلوب لأي موديل، في أي موديول. الـ trait بيضيف global scope (<code>App\\Support\\Organization\\OrganizationScopeConstraint</code>) بيفحص أنهي أعمدة من <code>entity_id</code>/<code>branch_id</code>/<code>department_id</code> موجودة فعليًا على جدول الموديل (قائمة أعمدة مخزّنة مؤقتًا لكل جدول، مش بتتستعلم كل صف) وبيفلتر بالتقاطع فوق — موديل عنده <code>entity_id</code> بس مش هيتأثر ببُعد الإدارة، والعكس صحيح.</p><p>مفيش مستخدم مسجّل دخول (queue worker، أمر console، مهمة مجدولة) → القيد بيرفض كل حاجة (<code>whereRaw(&#39;1 = 0&#39;)</code>). الوصول الشامل المشروع لازم يستثنى صراحة:</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Employee</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">withoutGlobalScope</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">OrganizationScopeConstraint</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::class</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;...</span></span></code></pre></div><p><code>OrganizationScopeResolver</code> نفسه بيعمل بالظبط كده داخليًا لما بيدوّر على سطر <code>Employee</code> بتاع المستخدم <strong>الحالي</strong> نفسه — حل النطاق لازم مايعتمدش أبدًا على نطاق بيتحسب هو نفسه من نفس السطر، وإلا كل بحث هيدخل في حلقة لا نهائية.</p><h2 id="سقوف-معلنة-متعمدة،-مش-منسية" tabindex="-1">سقوف معلنة (متعمدة، مش منسية) <a class="header-anchor" href="#سقوف-معلنة-متعمدة،-مش-منسية" aria-label="Permalink to &quot;سقوف معلنة (متعمدة، مش منسية)&quot;">​</a></h2><ul><li><strong>منح لمدير إقليمي/متعدد الفروع</strong> أوسع من قيمة واحدة في <code>entity_scope</code> — زي مدير على ٣ فروع محددين بالاسم — محتاج جدول إضافي <code>hr_employee_scope_grants</code>. لسه ماتبنيش؛ <code>entity_scope</code> لوحده بيغطي كل المطلوب حاليًا.</li><li><strong>صلاحيات على مستوى الحقل</strong> (زي إخفاء تكلفة مشروع عن مهندس، وإظهارها لمدير المشروع) مش آلية جديدة — هي <code>Column::visible()</code> / callbacks رؤية <code>ViewField</code> اللي محركات Dynamic Table/Record View بتدعمها أصلاً، محكومة بالصلاحية <em>الوظيفية</em> الخاصة بفعل الحقل ده بالتحديد.</li></ul>',32)])])}const k=o(s,[["render",d]]);export{g as __pageData,k as default};
